/**
 * 붙여 넣은 대화·메일에서 요청 후보를 뽑는다.
 *
 * 알아보는 형식
 *   카카오톡 PC 내보내기     [홍길동] [오후 3:12] 메시지      (날짜는 '--------------- 2026년 10월 5일 일요일 ---------------' 줄)
 *   카카오톡 모바일 내보내기 2026년 10월 5일 오후 3:12, 홍길동 : 메시지
 *                           2026. 10. 5. 오후 3:12, 홍길동 : 메시지   (iOS)
 *                           2026. 10. 5. 15:12, 홍길동 : 메시지        (24시간)
 *   그 밖의 글(메일 등)     번호·글머리표 줄마다 하나, 없으면 빈 줄로 나눈 문단마다 하나
 *
 * 여러 줄 메시지는 다음 머리줄이 나올 때까지 이어 붙인다.
 * 요청처럼 보이는 메시지(수정·추가·오류·부탁 …)에 suggested 를 켠다 — 고르는 건 사람이다.
 * 이 파일은 순수 함수만 둔다(테스트: tests/kakao.spec.ts).
 */

export type ParsedFormat = 'kakao' | 'list' | 'paragraphs';

export interface ParsedMessage {
  /** 0부터 */
  index: number;
  author: string;
  /** 원문에 적힌 시각(사람이 읽는 문자열) */
  at: string;
  text: string;
  suggested: boolean;
}

export interface ParseResult {
  format: ParsedFormat;
  messages: ParsedMessage[];
  authors: string[];
  /** 너무 길어 잘랐는가 */
  truncated: boolean;
}

export const MAX_INPUT = 200_000;
export const MAX_MESSAGES = 300;

const PC_DATE = /^-{3,}\s*(\d{4})년\s*(\d{1,2})월\s*(\d{1,2})일[^-]*-{3,}\s*$/;
const PC_LINE = /^\[([^\]\n]{1,40})\]\s*\[(오전|오후)\s*(\d{1,2}):(\d{2})\]\s?(.*)$/;
// 날짜 + (오전|오후)? + 시각 + 쉼표 + 이름 + ' : ' + 내용
const MOBILE_LINE =
  /^(\d{4})(?:년\s*|\.\s*)(\d{1,2})(?:월\s*|\.\s*)(\d{1,2})(?:일|\.)?\s*(오전|오후)?\s*(\d{1,2}):(\d{2}),\s*(.{1,40}?)\s:\s?(.*)$/;
// 날짜·시각으로 시작하지만 'X : ' 가 없는 줄 — 들어옴·나감 같은 알림
const MOBILE_SYSTEM = /^(\d{4})(?:년\s*|\.\s*)(\d{1,2})(?:월\s*|\.\s*)(\d{1,2})(?:일|\.)?\s*(오전|오후)?\s*(\d{1,2}):(\d{2}),?\s/;
// 날짜만 있는 줄(모바일 날짜 구분)
const MOBILE_DATE = /^(\d{4})(?:년\s*|\.\s*)(\d{1,2})(?:월\s*|\.\s*)(\d{1,2})(?:일|\.)?\s*([월화수목금토일]요일)?\s*$/;

const BULLET = /^\s*(?:[-*•·▪◦‣]|\d{1,3}[.)]|\(\d{1,3}\)|[①-⑳]|[가-하][.)])\s+/;
const QUOTE_STOP = [
  /^-{2,}\s*(original message|원본 메시지|원래 메시지|forwarded message|전달된 메시지)\s*-{2,}/i,
  /^on .{4,120} wrote:$/i,
  /^\d{4}.{2,60}(작성|님이 작성):$/,
  /^(from|보낸 사람|보낸사람)\s*:/i,
];

const NOISE = /^(사진|사진 \d+장|동영상|이모티콘|\(이모티콘\)|음성메시지|삭제된 메시지입니다\.?|메시지가 삭제되었습니다\.?|샵검색\s*:.*)$/;
const ACK =
  /^(네+|넵+|넹|예|응|ㅇㅇ|ㅇㅋ|오케이|ok|okay|감사합니다|고맙습니다|감사해요|확인했습니다|확인했어요|확인했습니다\s*감사합니다|알겠습니다|알겠어요|수고하세요|수고하셨습니다|수고 많으셨습니다|좋습니다|좋아요|안녕하세요|ㅎ+|ㅋ+|[!.~^ ]+)[!.~^ ]*$/i;
const HINT =
  /(수정|변경|바꿔|바꾸|바뀌|교체|추가|삭제|빼\s?주|빼고|빼야|넣어|넣고|고쳐|고치|오류|에러|버그|안\s?돼|안\s?되|안\s?나와|안\s?나옵|안\s?보|안\s?열|안\s?눌|깨져|깨지|틀려|틀린|잘못|이상해|이상하|이상합|느려|느립|확인\s?부탁|부탁|요청|해\s?주세요|해\s?주실|해주시|해\s?줘|해\s?주면|필요|원합니다|가능할까|가능한가|가능하면|가능할지|됐으면|되었으면|되면 좋|좋겠|맞춰|맞게|크게|작게|위로|아래로|빠져)/;

function hourOf(ampm: string | undefined, h: number): number {
  if (ampm === '오후' && h < 12) return h + 12;
  if (ampm === '오전' && h === 12) return 0;
  return h;
}

const fmtAt = (y: string | number, m: string | number, d: string | number, ampm: string | undefined, h: number, min: string) => {
  const hh = hourOf(ampm, h);
  return `${y}. ${Number(m)}. ${Number(d)}. ${String(hh).padStart(2, '0')}:${min}`;
};

function isSuggested(text: string): boolean {
  const t = text.trim();
  if (t.length < 6 || NOISE.test(t) || ACK.test(t)) return false;
  return HINT.test(t);
}

/** 제목 후보: 첫 줄, 글머리표 없이, 60자 */
export function suggestTitle(text: string): string {
  const first = text.split('\n').find((l) => l.trim()) ?? '';
  const t = first.replace(BULLET, '').replace(/\s+/g, ' ').trim();
  return t.length > 60 ? `${t.slice(0, 59)}…` : t;
}

function normalize(input: string): { lines: string[]; truncated: boolean } {
  const truncated = input.length > MAX_INPUT;
  const s = input.slice(0, MAX_INPUT).replace(/\r\n?/g, '\n').replace(/\u00a0/g, ' ');
  // eslint-disable-next-line no-control-regex
  return { lines: s.replace(/[\u0000-\u0008\u000b\u000c\u000e-\u001f\u007f\ufeff]/g, '').split('\n'), truncated };
}

function parseKakao(lines: string[]): ParsedMessage[] | null {
  let hits = 0;
  for (const l of lines) if (PC_LINE.test(l) || MOBILE_LINE.test(l)) hits++;
  if (hits === 0) return null;

  const out: Omit<ParsedMessage, 'index' | 'suggested'>[] = [];
  let date: [string, string, string] | null = null;
  let cur: Omit<ParsedMessage, 'index' | 'suggested'> | null = null;
  const flush = () => {
    if (cur) {
      cur.text = cur.text.replace(/\s+$/g, '');
      if (cur.text.trim()) out.push(cur);
    }
    cur = null;
  };

  for (const raw of lines) {
    const l = raw.replace(/\s+$/, '');
    let m = l.match(PC_DATE);
    if (m) {
      flush();
      date = [m[1], m[2], m[3]];
      continue;
    }
    m = l.match(PC_LINE);
    if (m) {
      flush();
      const at = date ? fmtAt(date[0], date[1], date[2], m[2], Number(m[3]), m[4]) : `${m[2]} ${m[3]}:${m[4]}`;
      cur = { author: m[1].trim(), at, text: m[5] };
      continue;
    }
    m = l.match(MOBILE_LINE);
    if (m) {
      flush();
      cur = { author: m[7].trim(), at: fmtAt(m[1], m[2], m[3], m[4], Number(m[5]), m[6]), text: m[8] };
      continue;
    }
    if (MOBILE_DATE.test(l) || MOBILE_SYSTEM.test(l)) {
      flush();
      continue;
    }
    // 첫 메시지 앞(내보내기 머리말)은 버린다
    if (cur) (cur as { text: string }).text += `\n${l}`;
  }
  flush();
  return out.map((x, i) => ({ ...x, index: i, suggested: false }));
}

function stripMail(lines: string[]): string[] {
  const out: string[] = [];
  for (const l of lines) {
    const t = l.trim();
    if (QUOTE_STOP.some((r) => r.test(t))) break;
    if (t.startsWith('>')) continue;
    out.push(l.replace(/\s+$/, ''));
  }
  return out;
}

function parseList(lines: string[]): ParsedMessage[] | null {
  const bulletCount = lines.filter((l) => BULLET.test(l)).length;
  if (bulletCount < 2) return null;
  const items: string[] = [];
  let cur: string | null = null;
  for (const l of lines) {
    if (BULLET.test(l)) {
      if (cur !== null) items.push(cur);
      cur = l.replace(BULLET, '').trim();
    } else if (cur !== null && l.trim()) {
      // 글머리표 아래 들여 쓴 줄은 이어 붙이고, 들여쓰기 없는 문단이 나오면 끝
      if (/^\s{2,}|^\t/.test(l)) cur += `\n${l.trim()}`;
      else {
        items.push(cur);
        cur = null;
      }
    } else if (cur !== null && !l.trim()) {
      items.push(cur);
      cur = null;
    }
  }
  if (cur !== null) items.push(cur);
  return items.filter((t) => t.trim()).map((text, index) => ({ index, author: '', at: '', text, suggested: false }));
}

function parseParagraphs(lines: string[]): ParsedMessage[] {
  const paras = lines.join('\n').split(/\n\s*\n/).map((p) => p.trim()).filter(Boolean);
  return paras.map((text, index) => ({ index, author: '', at: '', text, suggested: false }));
}

export function parseConversation(input: string): ParseResult {
  const { lines, truncated } = normalize(input);
  let format: ParsedFormat = 'kakao';
  let messages = parseKakao(lines);
  if (!messages) {
    const body = stripMail(lines);
    messages = parseList(body);
    format = 'list';
    if (!messages) {
      messages = parseParagraphs(body);
      format = 'paragraphs';
    }
  }
  const cut = messages.length > MAX_MESSAGES;
  messages = messages.slice(0, MAX_MESSAGES).map((m, index) => ({
    ...m,
    index,
    text: m.text.slice(0, 4000),
    // 글머리표 목록은 항목 하나하나가 요청일 때가 많다. 대화·문단은 요청 낱말이 있어야 고른다.
    suggested:
      format === 'list' ? !ACK.test(m.text.trim()) && !NOISE.test(m.text.trim()) && m.text.trim().length >= 4 : isSuggested(m.text),
  }));
  const authors = [...new Set(messages.map((m) => m.author).filter(Boolean))];
  return { format, messages, authors, truncated: truncated || cut };
}
import { test, expect } from '@playwright/test';
import { parseConversation, suggestTitle } from '../src/shared/kakao';

test.describe('카카오톡 PC 내보내기', () => {
  const text = [
    '하늘상회 님과 카카오톡 대화',
    '저장한 날짜 : 2026-10-05 15:20:11',
    '',
    '--------------- 2026년 10월 5일 일요일 ---------------',
    '[김고객] [오후 3:12] 메인 배너 이미지 가을 시안으로 바꿔주세요',
    '[김고객] [오후 3:13] 그리고 회원가입 버튼이',
    '모바일에서 안 눌려요',
    '[이개발] [오후 3:20] 네 확인했습니다',
    '[김고객] [오후 3:21] 사진',
    '--------------- 2026년 10월 6일 월요일 ---------------',
    '[김고객] [오전 12:05] 결제 완료 메일에 상호명이 틀려요',
  ].join('\n');

  test('메시지·보낸 사람·시각을 나누고 여러 줄을 잇는다', () => {
    const r = parseConversation(text);
    expect(r.format).toBe('kakao');
    expect(r.messages.map((m) => m.author)).toEqual(['김고객', '김고객', '이개발', '김고객', '김고객']);
    expect(r.messages[0].at).toBe('2026. 10. 5. 15:12');
    expect(r.messages[1].text).toBe('그리고 회원가입 버튼이\n모바일에서 안 눌려요');
    // 오전 12시는 0시
    expect(r.messages[4].at).toBe('2026. 10. 6. 00:05');
    expect(r.authors).toEqual(['김고객', '이개발']);
  });

  test('요청처럼 보이는 것만 미리 고른다', () => {
    const r = parseConversation(text);
    expect(r.messages.map((m) => m.suggested)).toEqual([true, true, false, false, true]);
  });
});

test.describe('카카오톡 모바일 내보내기', () => {
  test('안드로이드 형식, 알림 줄은 버린다', () => {
    const r = parseConversation(
      [
        '2026년 10월 5일 일요일',
        '2026년 10월 5일 오후 3:12, 김고객 : 상품 상세 이미지 순서 변경 부탁드립니다',
        '2026년 10월 5일 오후 3:13, 김고객님이 이개발님을 초대했습니다.',
        '2026년 10월 5일 오후 3:14, 이개발 : 넵',
      ].join('\n'),
    );
    expect(r.format).toBe('kakao');
    expect(r.messages).toHaveLength(2);
    expect(r.messages[0]).toMatchObject({ author: '김고객', at: '2026. 10. 5. 15:12', suggested: true });
    expect(r.messages[1]).toMatchObject({ author: '이개발', suggested: false });
  });

  test('iOS 형식과 24시간 표기, 이름에 공백', () => {
    const r = parseConversation(['2026. 10. 5. 오전 9:03, 김 과장 : 로고가 너무 작아요. 크게 해주세요', '2026. 10. 5. 21:40, 김 과장 : 감사합니다'].join('\n'));
    expect(r.messages[0]).toMatchObject({ author: '김 과장', at: '2026. 10. 5. 09:03', suggested: true });
    expect(r.messages[1]).toMatchObject({ at: '2026. 10. 5. 21:40', suggested: false });
  });

  test('내용 안의 " : " 는 자르지 않는다', () => {
    const r = parseConversation('2026. 10. 5. 오후 1:00, 김고객 : 문구 수정 : "무료배송" → "2만원 이상 무료배송"');
    expect(r.messages[0].text).toBe('문구 수정 : "무료배송" → "2만원 이상 무료배송"');
  });
});

test.describe('메일·그 밖의 글', () => {
  test('번호 목록은 항목마다 하나, 인용·이전 메일은 버린다', () => {
    const r = parseConversation(
      [
        '안녕하세요 대표님,',
        '어제 보내주신 시안 확인했습니다. 아래 수정 부탁드립니다.',
        '',
        '1. 메인 상단 문구를 “가을 신상”으로',
        '2) 푸터 전화번호 삭제',
        '   (대표번호는 아직 미정입니다)',
        '- 모바일 메뉴 글자 크기 키우기',
        '',
        '감사합니다.',
        '-----Original Message-----',
        '1. 이건 예전 메일',
        '> 2. 인용',
      ].join('\n'),
    );
    expect(r.format).toBe('list');
    expect(r.messages.map((m) => m.text)).toEqual([
      '메인 상단 문구를 “가을 신상”으로',
      '푸터 전화번호 삭제\n(대표번호는 아직 미정입니다)',
      '모바일 메뉴 글자 크기 키우기',
    ]);
    expect(r.messages.every((m) => m.suggested)).toBe(true);
  });

  test('목록이 없으면 문단, 인사 문단은 고르지 않는다', () => {
    const r = parseConversation('안녕하세요.\n\n결제 페이지에서 오류가 나요. 확인 부탁드립니다.\n\n감사합니다.');
    expect(r.format).toBe('paragraphs');
    expect(r.messages.map((m) => m.suggested)).toEqual([false, true, false]);
  });

  test('너무 긴 입력은 자르고 알린다', () => {
    const r = parseConversation(Array.from({ length: 400 }, (_, i) => `- 항목 ${i} 수정`).join('\n'));
    expect(r.messages).toHaveLength(300);
    expect(r.truncated).toBe(true);
  });
});

test('제목 후보: 첫 줄, 글머리표 없이, 60자', () => {
  expect(suggestTitle('- 메인 배너 교체\n자세한 내용')).toBe('메인 배너 교체');
  expect(suggestTitle('가'.repeat(80))).toHaveLength(60);
});
import { defineConfig, devices } from '@playwright/test';

/**
 * 시험.
 *   npm run build   # dist 를 만든다(시험은 빌드 결과를 wrangler dev 로 띄운다)
 *   npm test
 *
 * - unit: 붙여넣기 분석기, D1 선점 장치(getPlatformProxy), 공유 정의(강조색 대비·알림 분류) — 브라우저 없이
 * - api: 권한·승인·파일·알림을 HTTP 로 직접(화면에서 버튼을 숨기는 것으로 끝나지 않는지)
 * - desktop / mobile: 실제 브라우저로 개발업체·고객 화면 흐름
 * 서버를 Playwright 가 띄우면 로컬 D1 을 비우고 개발업체 하나(owner@studio.test)를 만든다.
 */
export default defineConfig({
  testDir: './tests',
  timeout: 120_000,
  expect: { timeout: 10_000 },
  // 가짜 Resend 의 메일 기록과 로컬 D1 을 함께 쓰므로 한 줄로
  workers: 1,
  reporter: [['list']],
  use: { locale: 'ko-KR', timezoneId: 'Asia/Seoul', trace: 'off', baseURL: 'http://127.0.0.1:8798' },
  webServer: [
    { command: 'node tests/mock-resend.mjs 8799', url: 'http://127.0.0.1:8799/__mails', reuseExistingServer: true },
    {
      command:
        'node scripts/db-local.mjs --persist-to .wrangler/test-state && npx wrangler dev --port 8798 --ip 127.0.0.1 --persist-to .wrangler/test-state --env-file tests/worker-test.env --test-scheduled',
      url: 'http://127.0.0.1:8798/api/me',
      reuseExistingServer: true,
      timeout: 180_000,
    },
  ],
  projects: [
    { name: 'unit', testMatch: /(kakao|guard|domain)\.spec/ },
    { name: 'api', testMatch: /api-.*\.spec/ },
    { name: 'desktop', testMatch: /ui-.*\.spec/, testIgnore: /ui-mobile/, use: { ...devices['Desktop Chrome'], viewport: { width: 1280, height: 800 } } },
    { name: 'mobile', testMatch: /ui-mobile\.spec/, use: { ...devices['Pixel 7'], viewport: { width: 360, height: 800 } } },
    // 화면 캡처는 npm run shots 로만(SHOTS=1)
    ...(process.env.SHOTS ? [{ name: 'shots', testMatch: /shots\.spec/ }] : []),
  ],
});
{
  "name": "client-irumx-app",
  "version": "0.9.0",
  "private": true,
  "type": "module",
  "description": "이룸검수(client.irumx.app) — 외주 개발의 작업 범위·추가 작업·납품 검수를 개발업체와 고객이 같은 화면에서 확인하는 멀티테넌트 SaaS",
  "engines": {
