+test.describe('절단 제한', () => {
+  const formats = [
+    { format: 'kakao', wrap: (bodies: string[]) => bodies.map((body) => `[김고객] [오후 3:12] ${body}`).join('\n'), author: '김고객', at: '오후 3:12' },
+    { format: 'list', wrap: (bodies: string[]) => bodies.map((body) => `- ${body}`).join('\n'), author: '', at: '' },
+    { format: 'paragraphs', wrap: (bodies: string[]) => bodies.join('\n\n'), author: '', at: '' },
+  ];
+
+  for (const { format, wrap, author, at } of formats) {
+    for (const length of [3999, 4000, 4001]) {
+      test(`${format}: 본문 ${length}자는 4,000자를 넘을 때만 절단을 알린다`, () => {
+        // 요청 낱말이 절단 경계에 걸려도 suggested는 원래 본문으로 판단한다.
+        const body = `${'가'.repeat(length - 2)}수정`;
+        const r = parseConversation(wrap([body, '감사합니다']));
+        expect(r.format).toBe(format);
+        expect(r.messages).toEqual([
+          { index: 0, author, at, text: body.slice(0, 4000), suggested: true },
+          { index: 1, author, at, text: '감사합니다', suggested: false },
+        ]);
+        expect(r.authors).toEqual(author ? [author] : []);
+        expect(r.truncated).toBe(length > 4000);
+      });
+    }
+
+    test(`${format}: 정규화와 본문 추출 후의 길이로 절단을 판단한다`, () => {
+      const body = `${'가'.repeat(3999)}\u0000나  `;
+      const r = parseConversation(wrap([body, '감사합니다']));
+      expect(r.format).toBe(format);
+      expect(r.messages[0].text).toBe(`${'가'.repeat(3999)}나`);
+      expect(r.truncated).toBe(false);
+    });
+
+    for (const count of [MAX_MESSAGES, MAX_MESSAGES + 1]) {
+      test(`${format}: 메시지 ${count}개는 300개를 넘을 때만 절단을 알린다`, () => {
+        const bodies = Array.from({ length: count }, (_, i) => `항목 ${i} 수정`);
+        const r = parseConversation(wrap(bodies));
+        expect(r.format).toBe(format);
+        expect(r.messages).toEqual(bodies.slice(0, MAX_MESSAGES).map((text, index) => ({ index, author, at, text, suggested: true })));
+        expect(r.truncated).toBe(count > MAX_MESSAGES);
+      });
+    }
+  }
+
+  for (const length of [MAX_INPUT, MAX_INPUT + 1]) {
+    test(`전체 입력 ${length}자는 200,000자를 넘을 때만 절단을 알린다`, () => {
+      // 개별 본문·메시지 개수 제한에 걸리지 않아 전체 입력 제한만 검증한다.
+      const body = '수정해 주세요';
+      const input = '\u0000'.repeat(MAX_INPUT - body.length) + body + (length > MAX_INPUT ? ' ' : '');
+      const r = parseConversation(input);
+      expect(input).toHaveLength(length);
+      expect(r.messages).toEqual([{ index: 0, author: '', at: '', text: body, suggested: true }]);
+      expect(r.truncated).toBe(length > MAX_INPUT);
+    });
+  }
+
+  test('본문 길이와 절단은 UTF-16 단위를 유지한다', () => {
+    const body = `${'가'.repeat(3999)}😀`;
+    const r = parseConversation(body);
+    expect(r.messages[0].text).toBe(body.slice(0, 4000));
+    expect(r.messages[0].text).toHaveLength(4000);
+    expect(r.truncated).toBe(true);
+  });
+});
